// services/futureLook.js
//
// Powers the interactive 3D model: when a user clicks the front/middle/rear
// section of the massing model, this decides which detected rooms sit in
// that section, and produces a description of what it could look like once
// built, in a chosen style. The actual illustration is rendered client-side
// as a procedural SVG (frontend/src/components/blueprint/SectionIllustration.jsx)
// using the palette this returns — no image-generation API is required, so
// this always works. If ANTHROPIC_API_KEY is set, the description text
// itself is generated by Claude for a richer result; otherwise a
// template-based generator produces a varied, still genuinely
// room-specific description.

const { createRng } = require("./seededRandom");
const { getAnthropicConfig } = require("./aiConfig");

const STYLE_PRESETS = {
  modern: {
    label: "Modern Minimalist",
    palette: { wall: "#EDF1F7", accent: "#2F80ED", floor: "#C7CEDA", trim: "#0A0F1C" },
    adjectives: ["clean-lined", "uncluttered", "light-filled", "understated"],
    materials: ["matte-finish flooring", "flush-panel doors", "concealed lighting", "large glazed windows"],
  },
  warm: {
    label: "Warm Contemporary",
    palette: { wall: "#F6EDE1", accent: "#F2994A", floor: "#C99A6A", trim: "#3B2A1A" },
    adjectives: ["inviting", "textured", "sunlit", "layered"],
    materials: ["warm wood flooring", "exposed wood beams", "woven textiles", "brass fixtures"],
  },
  classic: {
    label: "Classic Indian Traditional",
    palette: { wall: "#F3E7D0", accent: "#B5652B", floor: "#8C5A2B", trim: "#5A3B1E" },
    adjectives: ["ornate", "grounded", "symmetrical", "richly detailed"],
    materials: ["carved wooden accents", "terracotta or stone flooring", "jaali (lattice) screens", "traditional courtyard elements"],
  },
};

const SECTION_LABELS = { front: "Front section", middle: "Middle section", rear: "Rear section" };

// Splits detected rooms into front/middle/rear thirds based on their
// vertical position in the plan (box.yPct), which is the same axis the 3D
// model's depth segments are drawn along.
function buildSectionRooms(rooms, section) {
  const band = { front: [0, 33.3], middle: [33.3, 66.6], rear: [66.6, 100] }[section];
  const inBand = rooms.filter((r) => {
    const centreY = r.box.yPct + r.box.hPct / 2;
    return centreY >= band[0] && centreY < band[1];
  });
  if (inBand.length > 0) return inBand.map((r) => r.name);

  // Fallback: no room happened to centre in this exact band — pick the
  // closest ones instead of returning nothing.
  const targetY = (band[0] + band[1]) / 2;
  const sorted = [...rooms].sort((a, b) => {
    const ay = Math.abs(a.box.yPct + a.box.hPct / 2 - targetY);
    const by = Math.abs(b.box.yPct + b.box.hPct / 2 - targetY);
    return ay - by;
  });
  return sorted.slice(0, Math.min(2, sorted.length)).map((r) => r.name);
}

function templateDescription({ sectionLabel, rooms, style, variant }) {
  const preset = STYLE_PRESETS[style] || STYLE_PRESETS.modern;
  const rng = createRng(`${sectionLabel}-${style}-${variant}-${rooms.join("|")}`);

  const adjective = rng.pick(preset.adjectives);
  const material1 = rng.pick(preset.materials);
  const material2 = rng.pick(preset.materials.filter((m) => m !== material1));
  const roomList = rooms.length ? rooms.join(", ") : "this part of the plan";

  return (
    `Once built, the ${sectionLabel.toLowerCase()} — covering ${roomList} — takes on a ${adjective}, ` +
    `${preset.label.toLowerCase()} character. Expect ${material1} throughout, complemented by ${material2}. ` +
    `The palette leans on soft neutrals with a confident accent, keeping the space feeling considered rather ` +
    `than overdesigned — a finish that photographs well and wears well over time.`
  );
}

function stripCodeFences(text) {
  return text.trim().replace(/^```(json)?/i, "").replace(/```$/, "").trim();
}

async function aiDescription({ sectionLabel, rooms, style, projectType }) {
  const { apiKey, model } = getAnthropicConfig();
  if (!apiKey) throw new Error("No Anthropic API key configured");

  const preset = STYLE_PRESETS[style] || STYLE_PRESETS.modern;

  const prompt = `You are a residential interior designer describing how a section of a home will look once construction is complete.

Project type: ${projectType}
Section: ${sectionLabel}
Rooms in this section: ${rooms.join(", ") || "not specifically identified"}
Requested style: ${preset.label}

Write a vivid, concrete, 70-110 word description of how this section will look when finished, in this style. Mention specific finishes, materials, and how light and space feel. Avoid generic filler ("beautiful", "amazing"). Do not use markdown. Respond with ONLY the description text, nothing else.`;

  const response = await fetch("https://api.anthropic.com/v1/messages", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "x-api-key": apiKey,
      "anthropic-version": "2023-06-01",
    },
    body: JSON.stringify({
      model,
      max_tokens: 300,
      messages: [{ role: "user", content: prompt }],
    }),
  });

  if (!response.ok) {
    const errText = await response.text().catch(() => "");
    throw new Error(`Anthropic API request failed (${response.status}): ${errText.slice(0, 200)}`);
  }

  const data = await response.json();
  const textBlock = (data.content || []).find((c) => c.type === "text");
  if (!textBlock || !textBlock.text.trim()) throw new Error("Empty AI response");

  return stripCodeFences(textBlock.text);
}

async function generateFutureLook({ sectionLabel, rooms, style, variant, projectType }) {
  const resolvedStyle = STYLE_PRESETS[style] ? style : "modern";
  const preset = STYLE_PRESETS[resolvedStyle];
  const label = SECTION_LABELS[sectionLabel] || sectionLabel;

  let description;
  let source;
  try {
    description = await aiDescription({ sectionLabel: label, rooms, style: resolvedStyle, projectType });
    source = "ai-text";
  } catch (err) {
    description = templateDescription({ sectionLabel: label, rooms, style: resolvedStyle, variant });
    source = "demo-text";
  }

  return {
    section: sectionLabel,
    sectionLabel: label,
    style: resolvedStyle,
    styleLabel: preset.label,
    variant,
    rooms,
    palette: preset.palette,
    description,
    source,
    availableStyles: Object.entries(STYLE_PRESETS).map(([key, p]) => ({ key, label: p.label })),
  };
}

module.exports = { buildSectionRooms, generateFutureLook, STYLE_PRESETS };
